CREATE OR REPLACE FUNCTION public.mha_create_company_production_sku(p_store_id bigint, p_sku_code text, p_sku_name text, p_category text, p_base_price numeric, p_tax_applicable boolean DEFAULT true)\n RETURNS bigint\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_company bigint;v_id bigint;v_variant bigint;v_variant_code text;\nbegin\n select company_id into v_company from public.mha_current_store_context(p_store_id);\n if not public.mha_has_permission(v_company,'production','EDIT') then raise exception 'Production edit permission denied' using errcode='42501';end if;\n if length(trim(coalesce(p_sku_code,''))) not between 1 and 60 or length(trim(coalesce(p_sku_name,''))) not between 1 and 200 then raise exception 'Invalid SKU code or name';end if;\n if p_base_price is null or p_base_price<0 or p_base_price>1000000 then raise exception 'Invalid base price';end if;\n perform pg_advisory_xact_lock(v_company,99102);\n if exists(select 1 from public.production_sku where company_id=v_company and lower(sku_code)=lower(trim(p_sku_code))) then raise exception 'SKU code already exists in this company';end if;\n insert into public.production_sku(company_id,sku_code,sku_name,category,base_price,has_variation,is_active,tax_applicable)\n values(v_company,trim(p_sku_code),trim(p_sku_name),nullif(trim(coalesce(p_category,'')),''),p_base_price,false,true,coalesce(p_tax_applicable,true))\n returning id into v_id;\n v_variant_code:='MHA-BASE-'||v_id::text;\n insert into public.product_variant(production_sku_id,variant_code,variant_name,selling_price,is_active)\n values(v_id,v_variant_code,'Standard',p_base_price,true) returning id into v_variant;\n return v_id;\nend $function$\n

-- Explicit least-privilege grants are required on a fresh migration replay.
REVOKE ALL ON FUNCTION public.mha_create_company_production_sku(bigint,text,text,text,numeric,boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.mha_create_company_production_sku(bigint,text,text,text,numeric,boolean) TO authenticated;
